// ── Edge Function helpers ─────────────────────────────────────────────────────
async function callEdgeFn(fn: string, body: any, userToken?: string) {
  const headers: Record<string,string> = { "Content-Type": "application/json", "apikey": SUPA_KEY };
  if (userToken) headers["Authorization"] = `Bearer ${userToken}`;
  const res = await fetch(`${EDGE_URL}/${fn}`, { method: "POST", headers, body: JSON.stringify(body) });
  if (!res.ok) { const txt = await res.text().catch(() => ""); try { return JSON.parse(txt); } catch { return { error: `HTTP ${res.status}` }; } }
  return res.json();
}

// Prompt 28: Request ID generation
function generateRequestId(){return crypto.randomUUID();}

// Prompt 28: Payload key for idempotency lifecycle (frontend only, not security)
function getPayloadKey(sideA,sideB,tvA,tvB,scoring,posImpact,ageContext,draftCapital,rosterFit,warnings,formatNotes){
  const key={sideA:sideA.map(p=>({n:p.name,p:p.pos,v:p.val})),sideB:sideB.map(p=>({n:p.name,p:p.pos,v:p.val})),tvA,tvB,scoring:scoring||"PPR Dynasty",posImpact:posImpact?posImpact.map(p=>({p:p.pos,n:p.net})):null,ageContext:ageContext?{a:ageContext.avgA,b:ageContext.avgB}:null,draftCapital:draftCapital?{s:draftCapital.valSent,r:draftCapital.valReceived}:null,rosterFit:rosterFit?{t:rosterFit.team,d:rosterFit.valDelta}:null,warnings:warnings?[...warnings].sort():null,formatNotes:formatNotes?[...formatNotes].sort():null};
  return JSON.stringify(key);
}

function getVisitorId(): string {
  try {
    let id = localStorage.getItem("fdp_vid");
    if (!id) {
      id = "v_" + Math.random().toString(36).slice(2) + Date.now().toString(36);
      localStorage.setItem("fdp_vid", id);
    }
    return id;
  } catch { return "anonymous"; }
}

// Prompt 28: Fetch authoritative server quota status

let _trackedEmail = "";
function setTrackedUser(email: string) { _trackedEmail = email || ""; }

let _geoCache: {country:string;city:string;region:string;flag:string;ip:string}|null = null;
let _geoPromise: Promise<{country:string;city:string;region:string;flag:string;ip:string}|null>|null = null;
async function getGeo() {
  if (_geoCache) return _geoCache;
  if (_geoPromise) return _geoPromise;
  _geoPromise = (async () => {
    try {
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 3000);
      const r = await fetch("https://ipapi.co/json/", {signal: controller.signal});
      clearTimeout(timeout);
      const d = await r.json();
      _geoCache = {country: d.country_name||"Unknown", city: d.city||"", region: d.region||"", flag: d.country_code ? String.fromCodePoint(...[...d.country_code].map((c:string)=>0x1F1E6-65+c.charCodeAt(0))) : "", ip: d.ip||""};
    } catch { _geoCache = {country:"Unknown",city:"",region:"",flag:"",ip:""}; }
    return _geoCache;
  })();
  return _geoPromise;
}

async function trackEvent(type: string, data: Record<string, any> = {}) {
  const client = analyticsClient;
  if (!client) return;
  try {
    const result = await client.from("analytics_events").insert({
      visitor_id: getVisitorId(),
      event_type: type,
      event_data: _trackedEmail ? Object.assign({}, data, {user_email: _trackedEmail}) : data,
    });
    if (result.error) { /* silent */ }
  } catch(e) { /* silent */ }
}

