  async function handleCancelSubscription(){
    if(!user)return;
    setCancelLoading(true);
    try{
      var result=await callEdgeFn("cancel-subscription",{},user.token);
      if(result?.success){
        saveAndSetUser(Object.assign({},user,{plan:"free",isPro:false}));
        setCancelConfirm(false);
      }else{
        alert(result?.error||"Cancellation failed — please contact support.");
      }
    }catch(e){
      alert("Cancellation failed — please contact support.");
    }
    setCancelLoading(false);
  }
  async function checkSubscriptionAfterPayment(){
    if(!authClient)return;
    // Re-read user from localStorage to avoid stale closure
    var currentUser;
    try{var s=localStorage.getItem('fdp_user_v1');currentUser=s?JSON.parse(s):null;}catch(e){currentUser=null;}
    if(!currentUser)return;
    setPostPaymentLoading(true);
    setPostPaymentStatus("Checking your payment...");
    var maxAttempts=10;
    for(var i=0;i<maxAttempts;i++){
      try{
        var {data:sess}=await authClient.auth.getSession();
        if(!sess?.session){setPostPaymentStatus("Session expired — please log in again.");setPostPaymentLoading(false);return;}
        var {data:prof}=await authClient.from("users").select("id,plan,is_pro,subscription_status").eq("id",sess.session.user.id).single();
        if(prof?.is_pro){
          saveAndSetUser(Object.assign({},currentUser,{plan:prof.plan||"pro",isPro:true,subscriptionStatus:prof.subscription_status||"active"}));
          setShowPostPayment(false);setPostPaymentLoading(false);setPostPaymentStatus("");
          return;
        }
      }catch(e){}
      setPostPaymentStatus("Confirming with Stripe... ("+(i+1)+"/"+maxAttempts+")");
      await new Promise(function(r){setTimeout(r,2000);});
    }
    setPostPaymentLoading(false);
    setPostPaymentStatus("Payment not confirmed yet. If you completed checkout, please wait 1 minute and try again — or contact support.");
  }
  async function executeCheckout(plan:string,billing:string,authenticatedUser:any){
    if(!authenticatedUser){return;}
    setCheckoutLoading(true);setCheckoutErr("");
    // Open blank tab synchronously — browsers block window.open after any await
    var newTab=window.open("","_blank");
    function navigateTo(url:string){
      if(newTab&&!newTab.closed){newTab.location.href=url;}else{window.open(url,"_blank");}
      setCheckoutLoading(false);
      var onFocus=function(){window.removeEventListener("focus",onFocus);checkSubscriptionAfterPayment();};
      window.addEventListener("focus",onFocus);
      setTimeout(function(){window.removeEventListener("focus",onFocus);},1800000);
    }
    // Dynamic checkout — embeds supabase_user_id in metadata for reliable webhook matching
    try{
      var result=await callEdgeFn("create-checkout",{plan,billing,visitor_id:getVisitorId()},authenticatedUser.token);
      if(result?.url){navigateTo(result.url);return;}
      // Dynamic checkout returned no URL — show error
      console.error("create-checkout returned no URL:", result);
    }catch(e){
      console.error("create-checkout failed:", e);
    }
    // No insecure fallback — close the blank tab and show a retry-friendly error
    if(newTab)newTab.close();
    setCheckoutErr("Checkout failed — please try again. If the problem persists, contact support at fantasydraftproshelp@gmail.com");
    setCheckoutLoading(false);
  }
  function handleCheckout(plan:string,billing:string){
    if(!user){var intent={plan,billing};pendingCheckoutIntentRef.current=intent;setPendingCheckoutIntent(intent);setAuthMode("signup");setShowAuth(true);return;}
    executeCheckout(plan,billing,user);
  }
